// Construct a concrete ErrorLogger implementation for fuzzing.
// This avoids external dependencies and captures basic usage counts.
struct LocalLogger final : public ErrorLogger {
    // simple counters to exercise virtual calls without heavy I/O
    unsigned int outCount{0};
    unsigned int errCount{0};
    unsigned int metricCount{0};

    void reportOut(const std::string &outmsg, Color) override {
        // keep work bounded
        if (outmsg.size() > 4096u) return;
        ++outCount;
    }
    void reportErr(const ErrorMessage &msg) override {
        // touch a few fields to exercise accessors; avoid heavy string ops
        (void)msg.severity;
        (void)msg.certainty;
        ++errCount;
    }
    void reportMetric(const std::string &metric) override {
        if (metric.size() > 4096u) return;
        ++metricCount;
    }
};

